import { _decorator, Button, Component, Label } from 'cc';
import type { Bus } from '../../Engine/Bus';
import { BATTLE_EVENT } from '../../Battle/BattleEvents';

const { ccclass, property } = _decorator;

@ccclass('PauseButton')
export class PauseButton extends Component {

    @property(Label)
    label: Label = null!;

    @property(Button)
    button: Button = null!;

    private _bus: Bus = null!;
    private _isPaused = false;

    setup(bus: Bus): void {
        this._bus = bus;
        this._bus.on(BATTLE_EVENT.PAUSE_TOGGLED, this._onPauseToggled, this);
    }

    onLoad() {
        this.button.node.on(Button.EventType.CLICK, this._onClick, this);
        this._updateLabel();
    }

    onDestroy() {
        this.button.node.off(Button.EventType.CLICK, this._onClick, this);
        this._bus?.off(BATTLE_EVENT.PAUSE_TOGGLED, this._onPauseToggled, this);
    }

    private _onClick(): void {
        this._bus.emit(BATTLE_EVENT.PAUSE_TOGGLE_REQUEST);
    }

    /** BattleScene 暂停/继续后，发事件通知按钮更新显示 */
    private _onPauseToggled(paused: boolean): void {
        this._isPaused = paused;
        this._updateLabel();
    }

    private _updateLabel(): void {
        if (this.label) {
            this.label.string = this._isPaused ? '继续' : '暂停';
        }
    }
}